awk '
/\/api\/v[0-9]+\/internal\// {
  # Check if this is a 10.x.x.x health check to exclude
  if ($1 ~ /^10\./ && (/\/health/ || /\/ready/)) next;

  # Parse and convert timestamp
  match($0, /\[([0-9]{2})\/([A-Za-z]{3})\/([0-9]{4}):([0-9]{2}):([0-9]{2}):([0-9]{2})/, ts);

  # Month conversion
  months["Jan"]="01"; months["Feb"]="02"; months["Mar"]="03";
  months["Apr"]="04"; months["May"]="05"; months["Jun"]="06";
  months["Jul"]="07"; months["Aug"]="08"; months["Sep"]="09";
  months["Oct"]="10"; months["Nov"]="11"; months["Dec"]="12";

  # Build ISO timestamp
  iso_ts = ts[3] "-" months[ts[2]] "-" ts[1] "T" ts[4]":" ts[5] "-" ts[6];

  # Replace timestamp in line
  sub(/\[[^\]]+\]/, iso_ts);
  print;
}
' /var/log/app/access.log > /home/user/internal_hits.log

